package com.bank.dao;

import java.sql.*;
import javax.annotation.Resource;
import javax.sql.DataSource;

public class ClientDAO {

    @Resource(name = "jdbc/bankDB")
    private DataSource dataSource;

    public Client findById(long id) throws SQLException {
        Connection con = null;
        PreparedStatement ps = null;
        ResultSet rs = null;
        try {
            con = dataSource.getConnection();
            ps = con.prepareStatement("SELECT * FROM CLIENTS WHERE ID = ?");
            ps.setLong(1, id);
            rs = ps.executeQuery();
            if (rs.next()) {
                Client c = new Client();
                c.setId(rs.getLong("ID"));
                c.setName(rs.getString("NAME"));
                c.setEmail(rs.getString("EMAIL"));
                c.setBalance(rs.getBigDecimal("BALANCE"));
                return c;
            }
            return null;
        } finally {
            if (rs != null) rs.close();
            if (ps != null) ps.close();
            if (con != null) con.close();
        }
    }

    public List<Client> findAll() throws SQLException {
        List<Client> clients = new ArrayList<>();
        Connection con = dataSource.getConnection();
        Statement st = con.createStatement();
        ResultSet rs = st.executeQuery("SELECT * FROM CLIENTS ORDER BY NAME");
        while (rs.next()) {
            Client c = new Client();
            c.setId(rs.getLong("ID"));
            c.setName(rs.getString("NAME"));
            c.setEmail(rs.getString("EMAIL"));
            c.setBalance(rs.getBigDecimal("BALANCE"));
            clients.add(c);
        }
        rs.close(); st.close(); con.close();
        return clients;
    }
}
