package com.bank.web;

import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import java.io.*;
import com.google.gson.Gson;

@WebServlet("/api/clients/*")
public class ClientServlet extends HttpServlet {

    private ClientService clientService = new ClientService();
    private Gson gson = new Gson();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String pathInfo = req.getPathInfo();

        if (pathInfo == null || pathInfo.equals("/")) {
            List<Client> clients = clientService.findAll();
            resp.getWriter().write(gson.toJson(clients));
        } else {
            long id = Long.parseLong(pathInfo.substring(1));
            Client client = clientService.findById(id);
            if (client != null) {
                resp.getWriter().write(gson.toJson(client));
            } else {
                resp.setStatus(404);
                resp.getWriter().write("{"error":"Client not found"}");
            }
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        resp.setContentType("application/json");
        Client client = gson.fromJson(req.getReader(), Client.class);
        Client saved = clientService.create(client);
        resp.setStatus(201);
        resp.getWriter().write(gson.toJson(saved));
    }
}
