package com.bank.ws;

import javax.jws.WebService;
import javax.jws.WebMethod;
import javax.jws.WebParam;
import javax.jws.soap.SOAPBinding;

@WebService(serviceName = "PaymentService")
@SOAPBinding(style = SOAPBinding.Style.DOCUMENT)
public class PaymentWebService {

    @WebMethod
    public PaymentResponse processPayment(
            @WebParam(name = "amount") BigDecimal amount,
            @WebParam(name = "fromAccount") String fromAccount,
            @WebParam(name = "toAccount") String toAccount) {

        PaymentResponse response = new PaymentResponse();
        try {
            PaymentService service = ServiceLocator.lookup("PaymentService");
            String txId = service.executePayment(fromAccount, toAccount, amount);
            response.setTransactionId(txId);
            response.setStatus("SUCCESS");
        } catch (Exception e) {
            response.setStatus("FAILED");
            response.setErrorMessage(e.getMessage());
        }
        return response;
    }
}
