package com.bank.messaging;

import javax.ejb.MessageDriven;
import javax.ejb.ActivationConfigProperty;
import javax.jms.*;
import javax.ejb.EJB;

@MessageDriven(activationConfig = {
    @ActivationConfigProperty(propertyName = "destinationType", propertyValue = "javax.jms.Queue"),
    @ActivationConfigProperty(propertyName = "destination", propertyValue = "queue/PaymentQueue")
})
public class PaymentNotificationMDB implements MessageListener {

    @EJB
    private NotificationService notificationService;

    @EJB
    private AuditService auditService;

    @Override
    public void onMessage(Message message) {
        try {
            if (message instanceof TextMessage) {
                TextMessage textMsg = (TextMessage) message;
                String payload = textMsg.getText();

                PaymentEvent event = PaymentEvent.fromJson(payload);
                notificationService.sendPaymentConfirmation(event);
                auditService.logPaymentEvent(event);
            }
        } catch (JMSException e) {
            throw new RuntimeException("Error processing payment message", e);
        }
    }
}
