package com.bank.messaging;

import org.springframework.jms.annotation.JmsListener;
import org.springframework.stereotype.Component;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Component
@RequiredArgsConstructor
@Slf4j
public class PaymentNotificationListener {

    private final NotificationService notificationService;
    private final AuditService auditService;

    @JmsListener(destination = "payment-queue", containerFactory = "jmsListenerContainerFactory")
    public void onPaymentMessage(String payload) {
        try {
            PaymentEvent event = PaymentEvent.fromJson(payload);
            notificationService.sendPaymentConfirmation(event);
            auditService.logPaymentEvent(event);
            log.info("Payment notification processed: {}", event.getTransactionId());
        } catch (Exception e) {
            log.error("Error processing payment message", e);
            throw new RuntimeException("Error processing payment message", e);
        }
    }
