package com.bank.batch;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Component
@RequiredArgsConstructor
@Slf4j
public class InterestCalculationJob {

    private final AccountRepository accountRepository;

    @Scheduled(cron = "0 0 2 * * *")
    @Transactional
    public void calculateDailyInterest() {
        List<Account> accounts = accountRepository.findAllByActiveTrue();
        int processed = 0;
        for (Account account : accounts) {
            BigDecimal interest = account.getBalance()
                .multiply(account.getInterestRate())
                .divide(BigDecimal.valueOf(365), 2, RoundingMode.HALF_UP);
            account.credit(interest);
            accountRepository.save(account);
            processed++;
        }
        log.info("Daily interest calculated for {} accounts", processed);
    }
}
