package com.bank.util;

import javax.naming.InitialContext;
import javax.naming.NamingException;

public class ServiceLocator {

    private static InitialContext ctx;

    static {
        try {
            ctx = new InitialContext();
        } catch (NamingException e) {
            throw new RuntimeException("Failed to initialize JNDI context", e);
        }
    }

    @SuppressWarnings("unchecked")
    public static <T> T lookup(String jndiName) {
        try {
            return (T) ctx.lookup("java:comp/env/" + jndiName);
        } catch (NamingException e) {
            throw new RuntimeException("JNDI lookup failed: " + jndiName, e);
        }
    }

    public static DataSource getDataSource() {
        return lookup("jdbc/bankDB");
    }

    public static AccountService getAccountService() {
        return lookup("ejb/AccountService");
    }
}
