package com.bank.interceptor;

import javax.interceptor.AroundInvoke;
import javax.interceptor.Interceptor;
import javax.interceptor.InvocationContext;
import java.util.logging.Logger;

@Interceptor
public class AuditInterceptor {

    private static final Logger logger = Logger.getLogger(AuditInterceptor.class.getName());

    @AroundInvoke
    public Object audit(InvocationContext ctx) throws Exception {
        String method = ctx.getMethod().getName();
        String target = ctx.getTarget().getClass().getSimpleName();
        long start = System.currentTimeMillis();

        logger.info("AUDIT: " + target + "." + method + " - START");

        try {
            Object result = ctx.proceed();
            long duration = System.currentTimeMillis() - start;
            logger.info("AUDIT: " + target + "." + method + " - SUCCESS (" + duration + "ms)");
            return result;
        } catch (Exception e) {
            long duration = System.currentTimeMillis() - start;
            logger.severe("AUDIT: " + target + "." + method + " - FAILED (" + duration + "ms): " + e.getMessage());
            throw e;
        }
    }
}
