import ma.eai.boa.xbanking.util.Utility;
import ma.eai.boa.xbanking.util.WriteFlux;

@Stateless(name = "MdService")
@TransactionAttribute(TransactionAttributeType.REQUIRED)
@Remote(SynchroneService.class)
public class MadServices implements SynchroneService {
  @Resource(name = "jdbc/ebankdirect_xa")
  private static DataSource ebankdirect;
  @Resource(name = "jdbc/ebankdirect_ebankinterface_nonxa")
  private DataSource ebankinterface;
  @Resource(name = "jdbc/ebankdirect_dwhds_nonxa")
  private DataSource DWHDSXA;
  @Resource(name = "jdbc/ebankdirect_datacenterds_nonxa")
  private DataSource dataCenterDs;
  @Resource
  private SessionContext sctx;

  private static final MADCore madCore = new MADCore();
  static final String ACTIONPATHNAME = "flux/action";
  // traitement
  public Envelope Traitement(Envelope envIn) throws Throwable {
    Envelope envOut = new Envelope();

    // Récupérer l'action à exécuter
    String actionName = envIn.getNodeAsString(ACTIONPATHNAME);
    Log.info("Action à exécuter (brute): " + actionName);

    try {
      MadServiceAction actionEnum = convertOldActionNames(actionName);

      // Get the appropriate handler from the factory
      ActionHandler handler = ActionHandlerFactory.getHandler(actionEnum);

      if (handler == null) {
        // Handle unknown action
        Log.error("Handler non trouvé pour l'action: " + actionEnum);
        envOut = WriteFlux.writeFluxMSG("999", "Handler non trouvé pour l'action: " + actionEnum);
        return envOut;
      }

      // Set necessary resources on the handler
      handler.setEbankdirect(this.ebankdirect);
      handler.setDataCenterDs(this.dataCenterDs);
      handler.setSessionContext(this.sctx);

      // Call the handler's handle method
      envOut = handler.handle(envIn);

    } catch (Exception e) {
      Log.error("Erreur lors du traitement de l'action: " + actionName, e);
      envOut = WriteFlux.writeFluxMSG("999", "Erreur lors du traitement de l'action: " + e.getMessage());
    }

    return envOut;
  }

  // Méthode utilitaire pour convertir les anciens noms d'action
  private MadServiceAction convertOldActionNames(String actionName) {
    switch (actionName) {
    case "getBenificiaires":
      return MadServiceAction.GETBENIFICIAIRES;

    case "controlMontant":
      return MadServiceAction.CONTROLMONTANT;

    case "traitementMAD":
      return MadServiceAction.TRAITEMENTMAD;

    case "getListMadAttente":
      return MadServiceAction.GETLISTMADATTENTE;

    case "annulerMAD":
      return MadServiceAction.ANNULERMAD;

    case "getHistoMAD":
      return MadServiceAction.GETHISTOMAD;

    case "modifBenef":
      return MadServiceAction.MODIFBENEF;

    case "modifTelBenef":
      return MadServiceAction.MODIFTELBENEF;

    case "supfBenef":
      return MadServiceAction.SUPFBENEF;

    case "ajoutBenef":
      return MadServiceAction.AJOUTBENEF;

    case "isBenefEnregistre":
      return MadServiceAction.ISBENEFENREGISTRE;

    case "MadCoreAuth":
      return MadServiceAction.MADCOREAUTH;

    case "ConsulterEligibilite":
      return MadServiceAction.CONSULTERELIGIBILITE;

    default:
      throw new IllegalArgumentException("Action non reconnue: " + actionName);
    }
  }
  public Envelope process(Envelope envIn) throws Exception {

    Log.initLogTraceInfos(envIn);
    Log.setNewThreadId();
    Log.info("Appel du Service : MAD Unitaire pour l'action  " + envIn.getNodeAsString(ACTIONPATHNAME));
    Log.info("flux en entrée  fluxIN pour l'action :  " + envIn.getNodeAsString(ACTIONPATHNAME)
            + Parser.unmarshall(envIn.toString()));

    Envelope envOut = new Envelope();

    // traitement
    try {
      if (ebankdirect == null) {
        throw new Exception("Problème à l'instantiation de la datasource ebankdiret");
      }


      if (dataCenterDs == null) {
        throw new Exception("Problème à l'instantiation de la datasource dataCenterDs");
      }
      Log.info(envIn.getBody());
      envOut = this.Traitement(envIn);

    if (envIn.getNodeAsString(ACTIONPATHNAME).equals("traitementMAD")) {

        Log.info("flux en sortie traitement mad  flux out:  " + Parser.unmarshall(envOut.toString()));
        envOut = Parser.unmarshall(Parser.unmarshall(envOut.toString()).toString());
        String codee = envOut.getNodeAsString("flux/code");
        Log.info("code retour  traitement mad " + codee);

        if (!codee.equals("000")) {
          Log.info("sctx.setRollbackOnly() pour MAD ");
          sctx.setRollbackOnly();

        }

      }

    } catch (MadCoreError madCoreError) {
      Log.info("Erreur service MadCentralisee error", madCoreError.getError());
      Log.info("Erreur service MadCentralisee code", madCoreError.getCode());
      sctx.setRollbackOnly();
    }
    catch (Exception e) {
      Log.info("exeption Exception  Traitement MAD  ..." + e.getMessage());
      sctx.setRollbackOnly();
    } catch (Throwable e1) {
      Log.info("exeption Throwable Traitement MAD " + e1.getMessage());
      sctx.setRollbackOnly();
    }
    Log.info("fin traitement mad");
    Log.info("Flux out: ");
    Log.info(envOut);
    return envOut;
  }


}
