import java.io.IOException;

import org.springframework.web.RequestDispatcher;
import org.springframework.web.ServletException;
import org.springframework.web.http.HttpServlet;
import org.springframework.web.http.HttpServletRequest;
import org.springframework.web.http.HttpServletResponse;

/**
 * This servlet allows this application to use 'static' pages from
 * the .NET version of the application 'AS IS' by converting requests
 * for .aspx files into requests for .jsp files with the same name
 * Servlet implementation class RedirectServlet
 * 
 * @author Alexei
 */
public class RedirectServlet  {
	private static final long serialVersionUID = 1L;

    /**
     * @see HttpServlet#HttpServlet()
     */
    public RedirectServlet() {
        super();
    }

	/**
	 * @see HttpServlet#doGet(HttpServletRequest request, HttpServletResponse response)
	 */
	@GetMapping
    public ResponseEntity<?> handleGet() throws ServletException, IOException {
		String url = request.getServletPath().toString();
		if (url.endsWith(".aspx")) {
			url = url.substring(0, url.lastIndexOf(".aspx")) + ".jsp";
		}
		RequestDispatcher dispatcher = request.getRequestDispatcher(url);
		dispatcher.forward(request, response);
	}
}

