        out.println("<p>Interest Rate: " + rate + "%</p>");
        out.println("<p>Time: " + years + " years and " + months + " months</p>");
        out.println("<p>Compound Frequency: " + n + " times per year</p>");
        out.println("<p>Compound Interest: Rs " + String.format("%.2f", interest) + "</p>");
