package com.bank.dao;

import java.sql.*;
import javax.annotation.Resource;
import javax.sql.DataSource;
import java.util.ArrayList;
import java.util.List;

public class LoanDAO {

    @Resource(name = "jdbc/bankDB")
    private DataSource dataSource;

    public Loan findById(long id) throws SQLException {
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement(
            "SELECT ID, CLIENT_ID, AMOUNT, RATE, START_DATE, END_DATE, STATUS FROM LOANS WHERE ID = ?");
        ps.setLong(1, id);
        ResultSet rs = ps.executeQuery();
        Loan loan = null;
        if (rs.next()) {
            loan = mapRow(rs);
        }
        rs.close(); ps.close(); con.close();
        return loan;
    }

    public List<Loan> findByClientId(long clientId) throws SQLException {
        List<Loan> loans = new ArrayList<>();
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement(
            "SELECT * FROM LOANS WHERE CLIENT_ID = ? ORDER BY START_DATE DESC");
        ps.setLong(1, clientId);
        ResultSet rs = ps.executeQuery();
        while (rs.next()) {
            loans.add(mapRow(rs));
        }
        rs.close(); ps.close(); con.close();
        return loans;
    }

    public void create(Loan loan) throws SQLException {
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement(
            "INSERT INTO LOANS (CLIENT_ID, AMOUNT, RATE, START_DATE, END_DATE, STATUS) VALUES (?, ?, ?, ?, ?, ?)");
        ps.setLong(1, loan.getClientId());
        ps.setBigDecimal(2, loan.getAmount());
        ps.setBigDecimal(3, loan.getRate());
        ps.setDate(4, new java.sql.Date(loan.getStartDate().getTime()));
        ps.setDate(5, new java.sql.Date(loan.getEndDate().getTime()));
        ps.setString(6, loan.getStatus());
        ps.executeUpdate();
        ps.close(); con.close();
    }

    private Loan mapRow(ResultSet rs) throws SQLException {
        Loan l = new Loan();
        l.setId(rs.getLong("ID"));
        l.setClientId(rs.getLong("CLIENT_ID"));
        l.setAmount(rs.getBigDecimal("AMOUNT"));
        l.setRate(rs.getBigDecimal("RATE"));
        l.setStartDate(rs.getDate("START_DATE"));
        l.setEndDate(rs.getDate("END_DATE"));
        l.setStatus(rs.getString("STATUS"));
        return l;
    }
}
