package com.bank.dao;

import java.sql.*;
import javax.naming.InitialContext;
import javax.sql.DataSource;

public class TransactionDAO {

    private DataSource getDataSource() throws Exception {
        InitialContext ctx = new InitialContext();
        return (DataSource) ctx.lookup("java:comp/env/jdbc/bankDB");
    }

    public void insertTransaction(String accountId, BigDecimal amount, String type) throws Exception {
        Connection con = getDataSource().getConnection();
        PreparedStatement ps = con.prepareStatement(
            "INSERT INTO TRANSACTIONS (ACCOUNT_ID, AMOUNT, TYPE, TX_DATE) VALUES (?, ?, ?, CURRENT_TIMESTAMP)");
        ps.setString(1, accountId);
        ps.setBigDecimal(2, amount);
        ps.setString(3, type);
        ps.executeUpdate();
        ps.close(); con.close();
    }

    public BigDecimal getBalance(String accountId) throws Exception {
        Connection con = getDataSource().getConnection();
        PreparedStatement ps = con.prepareStatement(
            "SELECT SUM(CASE WHEN TYPE='CREDIT' THEN AMOUNT ELSE -AMOUNT END) AS BALANCE FROM TRANSACTIONS WHERE ACCOUNT_ID = ?");
        ps.setString(1, accountId);
        ResultSet rs = ps.executeQuery();
        BigDecimal balance = BigDecimal.ZERO;
        if (rs.next()) {
            balance = rs.getBigDecimal("BALANCE");
        }
        rs.close(); ps.close(); con.close();
        return balance != null ? balance : BigDecimal.ZERO;
    }

    public List<Transaction> getRecentTransactions(String accountId, int limit) throws Exception {
        List<Transaction> txList = new ArrayList<>();
        Connection con = getDataSource().getConnection();
        PreparedStatement ps = con.prepareStatement(
            "SELECT * FROM TRANSACTIONS WHERE ACCOUNT_ID = ? ORDER BY TX_DATE DESC LIMIT ?");
        ps.setString(1, accountId);
        ps.setInt(2, limit);
        ResultSet rs = ps.executeQuery();
        while (rs.next()) {
            Transaction tx = new Transaction();
            tx.setId(rs.getLong("ID"));
            tx.setAccountId(rs.getString("ACCOUNT_ID"));
            tx.setAmount(rs.getBigDecimal("AMOUNT"));
            tx.setType(rs.getString("TYPE"));
            tx.setDate(rs.getTimestamp("TX_DATE").toLocalDateTime());
            txList.add(tx);
        }
        rs.close(); ps.close(); con.close();
        return txList;
    }
}
