        Connection c = ds.getConnection();
        PreparedStatement ps = c.prepareStatement("SELECT * FROM CARDS WHERE CARD_NUMBER = ?");
        ps.setString(1, cardNumber);
        ResultSet rs = ps.executeQuery();
        Card card = null;
        if (rs.next()) {
            card = new Card();
            card.setId(rs.getLong("ID"));
            card.setCardNumber(rs.getString("CARD_NUMBER"));
            card.setHolderName(rs.getString("HOLDER_NAME"));
            card.setExpiryDate(rs.getDate("EXPIRY_DATE"));
            card.setStatus(rs.getString("STATUS"));
            card.setDailyLimit(rs.getBigDecimal("DAILY_LIMIT"));
        }
        rs.close(); ps.close(); c.close();
        return card;
    }

    public void updateStatus(long cardId, String newStatus) throws SQLException {
        Connection c = ds.getConnection();
        PreparedStatement ps = c.prepareStatement("UPDATE CARDS SET STATUS = ?, UPDATED_AT = CURRENT_TIMESTAMP WHERE ID = ?");
        ps.setString(1, newStatus);
        ps.setLong(2, cardId);
        ps.executeUpdate();
        ps.close(); c.close();
    }

    public void activateCard(String cardNumber) throws SQLException {
        Connection c = ds.getConnection();
        PreparedStatement ps = c.prepareStatement("UPDATE CARDS SET STATUS = 'ACTIVE', ACTIVATION_DATE = CURRENT_TIMESTAMP WHERE CARD_NUMBER = ? AND STATUS = 'PENDING'");
        ps.setString(1, cardNumber);
        int rows = ps.executeUpdate();
        ps.close(); c.close();
        if (rows == 0) throw new RuntimeException("Card not found or already activated");
    }
