public class NotificationDAO {

    @Resource(name = "jdbc/notifDB")
    private DataSource dataSource;

    public void saveNotification(String userId, String type, String message) throws SQLException {
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement(
            "INSERT INTO NOTIFICATIONS (USER_ID, TYPE, MESSAGE, SENT_AT, READ_FLAG) VALUES (?, ?, ?, CURRENT_TIMESTAMP, 0)");
        ps.setString(1, userId);
        ps.setString(2, type);
        ps.setString(3, message);
        ps.executeUpdate();
        ps.close(); con.close();
    }

    public List<Notification> getUnreadByUser(String userId) throws SQLException {
        List<Notification> list = new ArrayList<>();
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement(
            "SELECT * FROM NOTIFICATIONS WHERE USER_ID = ? AND READ_FLAG = 0 ORDER BY SENT_AT DESC");
        ps.setString(1, userId);
        ResultSet rs = ps.executeQuery();
        while (rs.next()) {
            Notification n = new Notification();
            n.setId(rs.getLong("ID"));
            n.setUserId(rs.getString("USER_ID"));
            n.setType(rs.getString("TYPE"));
            n.setMessage(rs.getString("MESSAGE"));
            n.setSentAt(rs.getTimestamp("SENT_AT").toLocalDateTime());
            list.add(n);
        }
        rs.close(); ps.close(); con.close();
        return list;
    }

    public void markAsRead(long notifId) throws SQLException {
        Connection con = dataSource.getConnection();
        PreparedStatement ps = con.prepareStatement("UPDATE NOTIFICATIONS SET READ_FLAG = 1 WHERE ID = ?");
        ps.setLong(1, notifId);
        ps.executeUpdate();
        ps.close(); con.close();
    }
}
