public class PaymentHibernateDAO {

    private SessionFactory sessionFactory = HibernateUtil.getSessionFactory();

    public List<Payment> findByDateRange(Date startDate, Date endDate) {
        Session session = sessionFactory.openSession();
        try {
            Query query = session.createQuery(
                "FROM Payment p WHERE p.paymentDate BETWEEN :start AND :end ORDER BY p.paymentDate DESC");
            query.setParameter("start", startDate);
            query.setParameter("end", endDate);
            return query.list();
        } finally {
            session.close();
        }
    }

    public BigDecimal getTotalPaymentsByAccount(String accountId) {
        Session session = sessionFactory.openSession();
        try {
            Query query = session.createQuery(
                "SELECT SUM(p.amount) FROM Payment p WHERE p.accountId = :accountId");
            query.setParameter("accountId", accountId);
            BigDecimal total = (BigDecimal) query.uniqueResult();
            return total != null ? total : BigDecimal.ZERO;
        } finally {
            session.close();
        }
    }

    public void batchInsert(List<Payment> payments) {
        Session session = sessionFactory.openSession();
        Transaction tx = session.beginTransaction();
        try {
            int count = 0;
            for (Payment payment : payments) {
                session.save(payment);
                if (++count % 50 == 0) {
                    session.flush();
                    session.clear();
                }
            }
            tx.commit();
        } catch (Exception e) {
            tx.rollback();
            throw e;
        } finally {
            session.close();
        }
    }
}
