public class ClientHibernateDAO {

    private SessionFactory sessionFactory = HibernateUtil.getSessionFactory();

    public List<Client> search(String keyword, int page, int pageSize) {
        Session session = sessionFactory.openSession();
        try {
            Criteria criteria = session.createCriteria(Client.class);
            if (keyword != null && !keyword.isEmpty()) {
                Disjunction or = Restrictions.disjunction();
                or.add(Restrictions.ilike("name", keyword, MatchMode.ANYWHERE));
                or.add(Restrictions.ilike("email", keyword, MatchMode.ANYWHERE));
                or.add(Restrictions.ilike("phone", keyword, MatchMode.ANYWHERE));
                criteria.add(or);
            }
            criteria.setFirstResult(page * pageSize);
            criteria.setMaxResults(pageSize);
            criteria.addOrder(Order.asc("name"));
            return criteria.list();
        } finally {
            session.close();
        }
    }

    public long count(String keyword) {
        Session session = sessionFactory.openSession();
        try {
            Criteria criteria = session.createCriteria(Client.class);
            if (keyword != null && !keyword.isEmpty()) {
                Disjunction or = Restrictions.disjunction();
                or.add(Restrictions.ilike("name", keyword, MatchMode.ANYWHERE));
                or.add(Restrictions.ilike("email", keyword, MatchMode.ANYWHERE));
                criteria.add(or);
            }
            criteria.setProjection(Projections.rowCount());
            return (Long) criteria.uniqueResult();
        } finally {
            session.close();
        }
    }
